// ============================================================================
// WiFi Credentials
// ============================================================================

bool nvs_write_wifi_credentials(const char *ssid, const char *password) {
    if (!ssid || !password)
        return false;

    bool ok = nvs_write_string(KEY_WIFI_SSID, ssid);
    ok = ok && nvs_write_string(KEY_WIFI_PWD, password);

    printf("[NVS] WiFi credentials %s\n", ok ? "saved" : "save failed");
    return ok;
}

bool nvs_read_wifi_ssid(char *buffer, size_t buffer_size) {
    return nvs_read_string(KEY_WIFI_SSID, buffer, buffer_size);
}

bool nvs_read_wifi_password(char *buffer, size_t buffer_size) {
    return nvs_read_string(KEY_WIFI_PWD, buffer, buffer_size);
}

bool nvs_has_wifi_credentials(void) {
    char ssid[NVS_MAX_SSID_LEN];
    return nvs_read_wifi_ssid(ssid, sizeof(ssid)) && strlen(ssid) > 0;
}

