static const char KEY_BACKEND_IP[] = "backend_ip";
static const char KEY_BACKEND_PORT[] = "backend_port";

bool nvs_write_backend_config(const char *ip, uint16_t port) {
    if (!ip) return false;
    
    bool ok = nvs_write_string(KEY_BACKEND_IP, ip);
    ok = ok && nvs_write_int32(KEY_BACKEND_PORT, (int32_t)port);
    
    printf("[NVS] Backend config %s: %s:%d\n", ok ? "saved" : "save failed", ip, port);
    return ok;
}

bool nvs_read_backend_ip(char *buffer, size_t buffer_size) {
    return nvs_read_string(KEY_BACKEND_IP, buffer, buffer_size);
}

uint16_t nvs_read_backend_port(void) {
    int32_t port = 0;
    nvs_read_int32(KEY_BACKEND_PORT, &port);
    return (uint16_t)(port > 0 ? port : 8500);  // Default to 8500
}